import{_ as r,o as t,c as a,a5 as o}from"./chunks/framework.Bt0SrEfo.js";const u=JSON.parse('{"title":"TypeScript 学习资源","description":"","frontmatter":{},"headers":[],"relativePath":"前端/typescript/16-resources.md","filePath":"前端/typescript/16-resources.md","lastUpdated":1789979447000}'),i={name:"前端/typescript/16-resources.md"};function l(p,e,s,n,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="typescript-学习资源" tabindex="-1">TypeScript 学习资源 <a class="header-anchor" href="#typescript-学习资源" aria-label="Permalink to &quot;TypeScript 学习资源&quot;">​</a></h1><h2 id="一、官方文档-必读" tabindex="-1">一、官方文档(必读) <a class="header-anchor" href="#一、官方文档-必读" aria-label="Permalink to &quot;一、官方文档(必读)&quot;">​</a></h2><ul><li><a href="https://www.typescriptlang.org/docs/" target="_blank" rel="noreferrer">TypeScript 官方文档(英文)</a>——最权威,新特性最先在这里发</li><li><a href="https://www.tslang.cn/" target="_blank" rel="noreferrer">TypeScript 中文文档</a>——社区翻译,基本同步</li></ul><p>官方文档从入门到高级类型全覆盖,<strong>每个章节都有可运行的 playground 例子</strong>——遇到不确定的类型行为直接打开 <a href="https://www.typescriptlang.org/play" target="_blank" rel="noreferrer">TypeScript Playground</a> 试一下。</p><hr><h2 id="二、推荐书" tabindex="-1">二、推荐书 <a class="header-anchor" href="#二、推荐书" aria-label="Permalink to &quot;二、推荐书&quot;">​</a></h2><ul><li><strong>《TypeScript 编程》(Programming TypeScript)</strong>——O&#39;Reilly 出品,入门 + 进阶,内容扎实</li><li><strong>《Effective TypeScript》</strong>——62 个具体实践,适合已经会 TS 想&quot;用好&quot;的人</li></ul><hr><h2 id="三、练习平台" tabindex="-1">三、练习平台 <a class="header-anchor" href="#三、练习平台" aria-label="Permalink to &quot;三、练习平台&quot;">​</a></h2><h3 id="_3-1-type-challenges-强烈推荐" tabindex="-1">3.1 type-challenges(强烈推荐) <a class="header-anchor" href="#_3-1-type-challenges-强烈推荐" aria-label="Permalink to &quot;3.1 type-challenges(强烈推荐)&quot;">​</a></h3><p><a href="https://github.com/type-challenges/type-challenges" target="_blank" rel="noreferrer">github.com/type-challenges/type-challenges</a></p><p>从简单到地狱级别的类型体操题集。面试遇到 &quot;Pick 实现&quot;、&quot;DeepReadonly&quot; 时这就是复习利器。<strong>前端面试 TS 高频题基本都来自这里</strong>。</p><p>推荐刷到中等难度(medium)就足够应付面试。</p><h3 id="_3-2-typescript-exercises" tabindex="-1">3.2 TypeScript Exercises <a class="header-anchor" href="#_3-2-typescript-exercises" aria-label="Permalink to &quot;3.2 TypeScript Exercises&quot;">​</a></h3><p><a href="https://typescript-exercises.github.io/" target="_blank" rel="noreferrer">typescript-exercises.github.io</a></p><p>偏基础,把 JS 重写成 TS 的练习。</p><hr><h2 id="四、优质博客-视频" tabindex="-1">四、优质博客/视频 <a class="header-anchor" href="#四、优质博客-视频" aria-label="Permalink to &quot;四、优质博客/视频&quot;">​</a></h2><ul><li><strong>TypeScript Deep Dive</strong>(中文:<a href="https://jkchao.gitbook.io/typescript-book/" target="_blank" rel="noreferrer">jkchao.gitbook.io/typescript-book</a>)——开源免费电子书,中文版质量很好</li><li><strong>Matt Pocock</strong>(Twitter/@mattpocockUk)——TS 团队外最大的 KOL,博客和视频质量极高</li><li><strong>Titian Cernicova-Dragomir</strong>(TS 团队核心成员)——<a href="https://kentcdodds.com/blog" target="_blank" rel="noreferrer">博客</a> 关于类型设计的文章</li></ul><hr><h2 id="五、playground-与工具" tabindex="-1">五、Playground 与工具 <a class="header-anchor" href="#五、playground-与工具" aria-label="Permalink to &quot;五、Playground 与工具&quot;">​</a></h2><ul><li><a href="https://www.typescriptlang.org/play" target="_blank" rel="noreferrer">TypeScript Playground</a>——浏览器内运行 TS,支持多版本切换</li><li><a href="https://replit.com/languages/typescript" target="_blank" rel="noreferrer">ts-repl</a>——Replit 的在线 TS REPL</li><li>VS Code 内置 TS Server,<strong>不需要任何插件就能获得最好的 TS 体验</strong></li></ul><hr><h2 id="六、社区" tabindex="-1">六、社区 <a class="header-anchor" href="#六、社区" aria-label="Permalink to &quot;六、社区&quot;">​</a></h2><ul><li>TypeScript GitHub: <a href="https://github.com/microsoft/TypeScript" target="_blank" rel="noreferrer">github.com/microsoft/TypeScript</a>——发 issue、提 PR、读 RFC</li><li>Stack Overflow <code>typescript</code> tag——90% 的常见问题这里都有答案</li></ul>',25)])])}const d=r(i,[["render",l]]);export{u as __pageData,d as default};
